"use client";
import { use, useEffect, useState } from "react";

interface RecipePageProps {
    params: Promise<{ id: string }>; // ❗ Promise, бо ми будемо розпаковувати
}

export const URL = 'https://www.themealdb.com/api/json/v1/1/search.php?s='

export default function RecipePage({ params }: RecipePageProps) {
    const { id } = use(params); // ❗ Використовуємо React.use()

    const [mealData, setMealData] = useState<any>(null);

    const getData = async () => {
        try {
            const res = await fetch(URL);
            const data = await res.json();

            const result = data.meals.filter((obj: any) => obj.idMeal === id);
            setMealData(result[0]); // беремо один об'єкт, бо це один рецепт
        } catch (e) {
            console.error(e);
        }
    };

    useEffect(() => {
        getData();
    }, []);

    return (
        <div className="flex justify-center p-8">
            {mealData ? (
                <div className="max-w-3xl">
                    <img src={mealData.strMealThumb} alt={mealData.strMeal} className="w-full max-w-lg object-cover rounded-xl mb-6" />
                    <h1 className="text-2xl font-bold mb-4 text-center">{mealData.strMeal}</h1>
                    <p className="text-gray-700">{mealData.strInstructions}</p>
                </div>
            ) : (
                <p>Loading...</p>
            )}
        </div>
    );
}
